insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('33eaa369-a9e9-5b0f-a707-571c8cfacd1e','09211534-a7c7-512a-84f2-a4394b693b2f','Die Untersicht',false,'Die Untersicht steht in Methode 1 oberhalb der Vorderansicht.',2) on conflict (id) do nothing;
