insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('a3ef05ca-8360-56cb-bb50-9d3ed914655a','965d6f16-0328-5c75-9472-3e5bbba16506','Die Fläche muss spanend bearbeitet werden.',false,'Materialabtrag wird durch einen zusätzlichen Querstrich am Zeichen gefordert, nicht durch den Kreis.',1) on conflict (id) do nothing;
