insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('fbde7fcc-acab-5a58-adcc-75cc8359f71b','965d6f16-0328-5c75-9472-3e5bbba16506','Die Fläche wird nicht geprüft.',false,'Ein Oberflächenzeichen macht eine Vorgabe und schließt eine Prüfung nicht aus.',4) on conflict (id) do nothing;
