insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('119f8b4f-7c11-5133-b74f-143ed4d4197d','6a4d3d80-bb51-511f-b635-866b4176fdb2','Der Durchmesser wird ausschließlich in der Draufsicht bemaßt.',false,'Der Durchmesser wird dort bemaßt, wo die Form am deutlichsten erkennbar ist.',1) on conflict (id) do nothing;
