insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('ee4cce14-92b4-5c6b-b370-f543ed3cfbaa','6a4d3d80-bb51-511f-b635-866b4176fdb2','Das Durchmesserzeichen steht hinter der Maßzahl.',false,'Das Zeichen steht immer vor der Maßzahl.',4) on conflict (id) do nothing;
