insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('26448ae1-8472-5207-bbf0-7a1c1d9a9af4','a720ad1e-cada-5c33-b3ea-54451d1f7759','Es ersetzt die Stückliste.',false,'Die Stückliste ist ein eigenes Dokument beziehungsweise ein eigener Bereich der Zeichnung.',1) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('b7ab76fc-b4e7-540b-872e-ac7ffb162d26','a720ad1e-cada-5c33-b3ea-54451d1f7759','Es gibt die Prüfmittel vor, mit denen gemessen werden muss.',false,'Prüfmittel werden im Prüfplan festgelegt.',2) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('06c2877e-61af-5626-8731-994139dc7307','a720ad1e-cada-5c33-b3ea-54451d1f7759','Es enthält ausschließlich die Toleranzen.',false,'Allgemeintoleranzen können dort vermerkt sein, sie sind aber nicht der Zweck des Schriftfelds.',3) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('403b99d5-d909-58d6-81df-8e038e434ff5','a720ad1e-cada-5c33-b3ea-54451d1f7759','Es enthält die Arbeitsanweisung für die Montage.',false,'Montageschritte stehen in der Arbeitsanweisung, nicht im Schriftfeld.',4) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('0a28437e-9e7a-5ff6-991f-cfba7b7f97cf','a720ad1e-cada-5c33-b3ea-54451d1f7759','Es enthält verwaltende Angaben wie Benennung, Zeichnungsnummer, Maßstab und Werkstoff.',true,'Das Schriftfeld fasst die identifizierenden und verwaltenden Angaben zur Zeichnung zusammen.',5) on conflict (id) do nothing;
insert into fragen (id,thema_id,typ,aufgabenstellung,schwierigkeit,status,kern,ki_generiert,quellenstufe,tabellenbuch_fundstelle,enthaelt_zahlenwert,quell_ref) values ('7b69c99b-f4ed-5294-a611-09b61f410a64','fd6e238a-8aa0-5dee-85a6-aa9c8db09969','mc','Eine Zeichnung trägt die Angabe „Maßstab 2:1“. Was bedeutet das?',2,'entwurf',true,false,2,null,false,'PT-TU-107') on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('d3d5fd2e-99ab-5811-ae1e-8e0b3bb891e7','7b69c99b-f4ed-5294-a611-09b61f410a64','Das Werkstück ist doppelt so groß gezeichnet wie in Wirklichkeit.',true,'Bei 2:1 handelt es sich um eine Vergrößerung; die eingetragenen Maßzahlen bleiben aber die wirklichen Maße.',1) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('666baaaf-61dd-5394-a2db-c3dab68a9116','7b69c99b-f4ed-5294-a611-09b61f410a64','Die eingetragenen Maßzahlen müssen verdoppelt werden.',false,'Maßzahlen geben immer die wirkliche Größe an und werden nie umgerechnet.',2) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('134b4656-02ec-5c5f-9c23-375821dc9cf8','7b69c99b-f4ed-5294-a611-09b61f410a64','Die Zeichnung ist ohne Maßstab erstellt.',false,'Eine Zeichnung ohne Maßstab trägt die Angabe „ohne Maßstab“ oder „o. M.“.',3) on conflict (id) do nothing;
