insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('d09b3a98-9724-527b-b6b6-7d1ab121975b','456815d3-fbfa-5955-adce-b0ae963162a8','σ = 15 N/mm²',false,'Hier wurde kN nicht in N umgerechnet.',3) on conflict (id) do nothing;
insert into antwortoptionen (id,frage_id,text,ist_korrekt,erklaerung,reihenfolge) values ('d196fe95-74ba-5727-a398-ae767a1ffad3','456815d3-fbfa-5955-adce-b0ae963162a8','σ = 150 N/mm²',true,'σ = F / S = 30 000 N / 200 mm² = 150 N/mm².',4) on conflict (id) do nothing;
